create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name,role_code) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),'operator') on conflict(id) do nothing;return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and is_active and role_code in('administrator','stock_accountant'))$$;
create or replace function public.upsert_commodity(p_payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare id uuid;old jsonb;begin if not is_admin() then raise exception 'Administrator permission required';end if;if nullif(p_payload->>'id','') is null then insert into commodities(code,name,category,default_uom,inward_packing_mode,outward_packing_mode,inward_weight_basis,outward_weight_basis,inventory_quantity_basis,standard_net_weight_per_bag_kg,standard_empty_bag_tare_kg,bags_mandatory_inward,bags_mandatory_outward,is_active) values(upper(p_payload->>'code'),p_payload->>'name',p_payload->>'category',p_payload->>'default_uom',(p_payload->>'inward_packing_mode')::packing_mode,(p_payload->>'outward_packing_mode')::packing_mode,(p_payload->>'inward_weight_basis')::weight_basis,(p_payload->>'outward_weight_basis')::weight_basis,(p_payload->>'inventory_quantity_basis')::weight_basis,(p_payload->>'standard_net_weight_per_bag_kg')::numeric,(p_payload->>'standard_empty_bag_tare_kg')::numeric,coalesce((p_payload->>'bags_mandatory_inward')::boolean,false),coalesce((p_payload->>'bags_mandatory_outward')::boolean,false),true) returning commodities.id into id;else id:=(p_payload->>'id')::uuid;select to_jsonb(c) into old from commodities c where c.id=id;update commodities set name=p_payload->>'name',category=p_payload->>'category',default_uom=p_payload->>'default_uom',inward_packing_mode=(p_payload->>'inward_packing_mode')::packing_mode,outward_packing_mode=(p_payload->>'outward_packing_mode')::packing_mode,inward_weight_basis=(p_payload->>'inward_weight_basis')::weight_basis,outward_weight_basis=(p_payload->>'outward_weight_basis')::weight_basis,inventory_quantity_basis=(p_payload->>'inventory_quantity_basis')::weight_basis,standard_net_weight_per_bag_kg=(p_payload->>'standard_net_weight_per_bag_kg')::numeric,standard_empty_bag_tare_kg=(p_payload->>'standard_empty_bag_tare_kg')::numeric,bags_mandatory_inward=coalesce((p_payload->>'bags_mandatory_inward')::boolean,false),bags_mandatory_outward=coalesce((p_payload->>'bags_mandatory_outward')::boolean,false),updated_at=now() where commodities.id=id;insert into commodity_rule_versions(commodity_id,version_no,snapshot,created_by) select id,coalesce(max(version_no),0)+1,old,auth.uid() from commodity_rule_versions where commodity_id=id;end if;return id;end$$;
create or replace function public.create_pledge(p_payload jsonb) returns text language plpgsql security definer set search_path=public as $$declare p bank_pledges;ref text;lot uuid;qty numeric;begin ref:=next_reference('PLG',(select code from banks where id=(p_payload->>'bank_id')::uuid));insert into bank_pledges(pledge_no,bank_id,collateral_manager_id,bank_reference,collateral_manager_number,pledge_date,due_date,bank_value,funding_done) values(ref,(p_payload->>'bank_id')::uuid,nullif(p_payload->>'collateral_manager_id','')::uuid,p_payload->>'bank_reference',p_payload->>'collateral_manager_number',current_date,nullif(p_payload->>'due_date','')::date,coalesce((p_payload->>'bank_value')::numeric,0),coalesce((p_payload->>'funding_done')::numeric,0)) returning * into p;lot:=(p_payload->>'lot_id')::uuid;qty:=uom_to_kg((p_payload->>'qty')::numeric,p_payload->>'uom');if lot_balance(lot)-lot_controlled_qty(lot,null)<qty then raise exception 'Insufficient free stock for pledge';end if;insert into pledge_lots(pledge_id,lot_id,pledged_qty_kg) values(p.id,lot,qty);insert into stock_controls(control_type,lot_id,pledge_id,quantity_kg,reference_no) values('pledge',lot,p.id,qty,ref);return ref;end$$;
create or replace function public.release_pledge(p_payload jsonb) returns text language plpgsql security definer set search_path=public as $$declare ref text;p pledge_lots%rowtype;qty numeric;begin select * into p from pledge_lots where pledge_id=(p_payload->>'pledge_id')::uuid and lot_id=(p_payload->>'lot_id')::uuid for update;qty:=uom_to_kg((p_payload->>'qty')::numeric,p_payload->>'uom');if qty>p.pledged_qty_kg-p.released_qty_kg then raise exception 'Release exceeds outstanding pledge';end if;ref:=next_reference('PLGR','BANK');update pledge_lots set released_qty_kg=released_qty_kg+qty where id=p.id;update stock_controls set quantity_kg=quantity_kg-qty,status=case when quantity_kg-qty<=0 then 'released' else status end where pledge_id=p.pledge_id and lot_id=p.lot_id and status='active';insert into pledge_releases(release_no,pledge_id,release_date,released_qty_kg,bank_release_reference,collateral_release_reference,funding_reduced) values(ref,p.pledge_id,current_date,qty,p_payload->>'bank_release_reference',p_payload->>'collateral_release_reference',coalesce((p_payload->>'funding_reduced')::numeric,0));return ref;end$$;
create or replace function public.create_bulk_fumigation(p_payload jsonb) returns text language plpgsql security definer set search_path=public as $$declare ref text;f uuid;lot jsonb;begin ref:=next_reference('FUM',(select state_code||'-'||code from godowns where id=(p_payload->>'godown_id')::uuid));insert into fumigations(reference_no,fumigation_date,godown_id,chemical,chemical_batch,dosage,chemical_qty,contractor,responsible_employee,start_at,release_at,coverage_status,certificate_no,next_due_date,remarks) values(ref,current_date,(p_payload->>'godown_id')::uuid,p_payload->>'chemical',p_payload->>'chemical_batch',p_payload->>'dosage',nullif(p_payload->>'chemical_qty','')::numeric,p_payload->>'contractor',p_payload->>'responsible_employee',nullif(p_payload->>'start_at','')::timestamptz,nullif(p_payload->>'release_at','')::timestamptz,p_payload->>'coverage_status',p_payload->>'certificate_no',nullif(p_payload->>'next_due_date','')::date,p_payload->>'remarks') returning id into f;for lot in select * from jsonb_array_elements(p_payload->'lots') loop insert into fumigation_lots(fumigation_id,lot_id,treated_qty_kg) values(f,(lot->>'lot_id')::uuid,(lot->>'treated_qty_kg')::numeric);end loop;return ref;end$$;
create or replace function public.generate_operational_alerts() returns integer language plpgsql security definer set search_path=public as $$declare n integer;begin delete from alerts where status='open' and alert_type in('pledge_due','fumigation_due','pending_approval');insert into alerts(alert_type,severity,title,message,entity_type,entity_id,due_date) select 'pledge_due',case when due_date<current_date then 'critical' else 'warning' end,'Bank pledge due',pledge_no||' is due on '||due_date,'bank_pledge',id,due_date from bank_pledges where status='active' and due_date<=current_date+30;insert into alerts(alert_type,severity,title,message,entity_type,entity_id,due_date) select 'fumigation_due',case when next_due_date<current_date then 'critical' else 'warning' end,'Fumigation due',reference_no||' requires attention','fumigation',id,next_due_date from fumigations where next_due_date<=current_date+7;insert into alerts(alert_type,severity,title,message,entity_type,entity_id) select 'pending_approval','warning','Approval pending',reference_no||' is awaiting independent approval','inventory_transaction',id from inventory_transactions where status='pending_approval' and created_at<now()-interval '4 hours';select count(*) into n from alerts where status='open';return n;end$$;
grant execute on function upsert_commodity(jsonb),create_pledge(jsonb),release_pledge(jsonb),create_bulk_fumigation(jsonb) to authenticated;
